1	/**
2	 * CEO & Board — Strategic Decision-Making Agent Team
3	 *
4	 * v1 deliberation engine. Registers `converse` and `end_deliberation`
5	 * custom tools, spawns board member Pi agent subprocesses with persistent
6	 * sessions, logs all conversations to .jsonl, and renders board member
7	 * responses in the TUI.
8	 *
9	 * Usage: pi -e extensions/ceo-and-board.ts
10	 *        or auto-loaded via .pi/settings.json
11	 */
12	
13	import { spawn } from "node:child_process";
14	import {
15		existsSync,
16		readFileSync,
17		writeFileSync,
18		mkdirSync,
19		readdirSync,
20		statSync,
21	} from "node:fs";
22	import { join, basename } from "node:path";
23	import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
24	import { parseFrontmatter } from "@mariozechner/pi-coding-agent";
25	import { Text, truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";
26	import { Type } from "@sinclair/typebox";
27	
28	// ── Module imports ───────────────────────────────────────────────
29	import type { CeoConfig, MeetingState, MemberStats, ConstraintState, BoardMemberConfig } from "./modules/types";
30	import { findProjectRoot, parseConfig, loadBoardMembers, loadDotEnv, buildExpertiseBlock, buildSkillsBlock } from "./modules/config";
31	import { bgWarm, cyan, pink, yellow, green, dim, bold, parseHexColor, formatTokenCount, renderGaugeLine, renderBoardStatusLines } from "./modules/theme";
32	import { callBoardMember } from "./modules/subprocess";
33	import { generateSessionId, parseBudget, appendToLog, trimToolArgs, appendToolUse, getConstraintState } from "./modules/helpers";
34	
35	// ── Extension ────────────────────────────────────────────────────
36	
37	export default function (pi: ExtensionAPI) {
38		// ── State variables ──────────────────────────────────────────
39		let config: CeoConfig | null = null;
40		let meetingState: MeetingState | null = null;
41		let memberStats: Map<string, MemberStats> = new Map();
42		let projectRoot: string | null = null;
43		let subprocessEnv: Record<string, string> = { ...process.env } as Record<string, string>;
44		const respondingMembers: Set<string> = new Set();
45		let ceoCost: number = 0;
46	
47		// ── Helper: register constraint gauge widget ────────────────
48		// Extracted so it can be re-registered (moved to end of widget
49		// insertion order) after the board live-feed widget is set.
50	
51		let gaugeCtx: { ui: any } | null = null;
52	
53		function registerConstraintGauges() {
54			if (!gaugeCtx) return;
55			// Remove first to move to end of Map insertion order
56			gaugeCtx.ui.setWidget("constraint-gauges", undefined);
57			gaugeCtx.ui.setWidget("constraint-gauges", () => ({
58				render(width: number): string[] {
59					if (!config || !meetingState) return [];
60	
61					const c = config.meeting.constraints;
62					const minTime = c.min_time_minutes;
63					const maxTime = c.max_time_minutes;
64					const minBudget = parseBudget(c.min_budget);
65					const maxBudget = parseBudget(c.max_budget);
66	
67					const isActive =
68						meetingState.phase === "deliberating" || meetingState.phase === "ending";
69					const isComplete = meetingState.phase === "complete";
70					const currentTime =
71						isActive || isComplete
72							? (Date.now() - meetingState.startTime) / 1000 / 60
73							: 0;
74					const currentBudget = meetingState.budgetSpent;
75	
76					const barWidth = Math.max(10, width - 39);
77					const pad = bgWarm(" ".repeat(width));
78	
79					const timeLine = renderGaugeLine(
80						"TIME",
81						currentTime,
82						minTime,
83						maxTime,
84						barWidth,
85						`${currentTime.toFixed(1)} min`,
86						`${minTime}-${maxTime} min`,
87						width,
88					);
89	
90					const budgetLine = renderGaugeLine(
91						"BUDGET",
92						currentBudget,
93						minBudget,
94						maxBudget,
95						barWidth,
96						`$${currentBudget.toFixed(2)}`,
97						`${c.min_budget}-${c.max_budget}`,
98						width,
99					);
100	
101					return [pad, timeLine, budgetLine, pad];
102				},
103				invalidate() {},
104			}));
105		}
106	
107		// ── registerMessageRenderer("board-response") ────────────────
108	
109		pi.registerMessageRenderer("board-response", (message, _options, theme) => {
110			const details = message.details as { member?: string; color?: string } | undefined;
111			const memberName = details?.member || "Board Member";
112			const color = details?.color || "#ffffff";
113			const { r, g, b } = parseHexColor(color);
114	
115			const bgOpen = `\x1b[48;2;${r};${g};${b}m`;
116			const fgDark = `\x1b[38;2;30;30;30m`;
117			const reset = `\x1b[0m`;
118	
119			const header = `${bgOpen}${fgDark} ${memberName} ${reset}`;
120			const body = typeof message.content === "string" ? message.content : "";
121	
122			let text = header + "\n" + theme.fg("dim", body);
123			return new Text(text, 0, 0);
124		});
125	
126		// ── registerTool("converse") ─────────────────────────────────
127	
128		pi.registerTool({
129			name: "converse",
130			label: "Converse",
131			description:
132				"Send a message to one or more board members. Use `to` to address specific members by name, an array of names, or \"all\" to address the entire board. Returns their responses and the current constraint state (time/budget).",
133			promptSnippet:
134				'Send a message to board members. to: member name, array of names, or "all". Returns responses + constraint state.',
135			promptGuidelines: [
136				'ALWAYS default to converse("all", message) to broadcast to the entire board. Only address individual members for targeted follow-ups on specific arguments.',
137				'Do NOT loop through members individually with the same message. Use "all" to let all members respond in one call.',
138				"Check constraint_state in every response: if hit_max is true, call end_deliberation immediately.",
139				"If approaching_max_time or approaching_max_budget, start wrapping up.",
140			],
141			parameters: Type.Object({
142				to: Type.Union([Type.String(), Type.Array(Type.String())], {
143					description:
144						'Board member name, array of names, or "all" to address the entire board',
145				}),
146				message: Type.String({
147					description: "The CEO's question, challenge, follow-up, or directive",
148				}),
149			}),
150	
151			async execute(_toolCallId, params, signal, onUpdate, ctx) {
152				if (!meetingState || meetingState.phase !== "deliberating") {
153					throw new Error(
154						"No active deliberation. Use /ceo-begin to start a meeting first.",
155					);
156				}
157	
158				// Check if max already hit
159				const preCheck = getConstraintState(meetingState);
160				if (preCheck.hit_max) {
161					throw new Error(
162						"Meeting constraints exceeded. You MUST call end_deliberation immediately to collect final statements and write the memo.",
163					);
164				}
165	
166				const { to, message } = params;
167	
168				// Resolve target members
169				let targetMembers: BoardMemberConfig[] = [];
170				if (to === "all") {
171					targetMembers = [...meetingState.activeMembers];
172				} else if (typeof to === "string") {
173					const found = meetingState.activeMembers.find(
174						(m) => m.name.toLowerCase() === to.toLowerCase(),
175					);
176					if (!found) {
177						throw new Error(
178							`Board member "${to}" not found. Available: ${meetingState.activeMembers.map((m) => m.name).join(", ")}`,
179						);
180					}
181					targetMembers = [found];
182				} else if (Array.isArray(to)) {
183					for (const name of to) {
184						const found = meetingState.activeMembers.find(
185							(m) => m.name.toLowerCase() === name.toLowerCase(),
186						);
187						if (!found) {
188							throw new Error(
189								`Board member "${name}" not found. Available: ${meetingState.activeMembers.map((m) => m.name).join(", ")}`,
190							);
191						}
192						targetMembers.push(found);
193					}
194				}
195	
196				if (targetMembers.length === 0) {
197					throw new Error("No valid board members specified.");
198				}
199	
200				// Log CEO prompt (once for all targets)
201				const toField = targetMembers.length === meetingState.activeMembers.length
202					? "all"
203					: targetMembers.map((m) => m.name).join(", ");
204				appendToLog(meetingState.logPath, {
205					from: "CEO",
206					to: toField,
207					message,
208					timestamp: new Date().toISOString(),
209					type: "prompt",
210				});
211	
212				// Call all board members in PARALLEL
213				const perMemberText: Map<string, string> = new Map();
214				for (const m of targetMembers) {
215					perMemberText.set(m.name, "");
216					respondingMembers.add(m.name);
217				}
218	
219				// Single streaming widget — renders ALL members in config order
220				// (same approach as the footer: one render, fixed order, no shuffling)
221				const memberState: Map<string, { text: string; active: boolean }> = new Map();
222	
223				const refreshBoardWidget = () => {
224					ctx.ui.setWidget("board-live-feed", () => ({
225						render(rawWidth: number): string[] {
226							const width = Math.floor(rawWidth * 0.9);
227							const allLines: string[] = [];
228	
229							// Render ALL active members in config order
230							for (const m of meetingState!.activeMembers) {
231								const state = memberState.get(m.name);
232								if (!state) continue;
233	
234								const { r, g, b } = parseHexColor(m.color);
235								const bgOpen = `\x1b[48;2;${r};${g};${b}m`;
236								const fgDark = `\x1b[38;2;30;30;30m`;
237								const reset = `\x1b[0m`;
238	
239								const icon = state.active ? "\u{1F4AC}" : "\u{2705}";
240								const status = state.active ? " responding..." : " done";
241								const header = `${bgOpen}${fgDark} ${icon} ${m.name}${status} ${reset}`;
242								const headerLine = truncateToWidth(header + " ".repeat(rawWidth), rawWidth, "");
243	
244								const lines = state.text.split("\n").filter((l) => l.trim());
245								const lastLine = lines[lines.length - 1] || "";
246								const contentLine = truncateToWidth(
247									"  " + dim(lastLine) + " ".repeat(width),
248									width,
249									"",
250								);
251	
252								allLines.push(headerLine, contentLine);
253							}
254	
255							return allLines;
256						},
257						invalidate() {},
258					}));
259					// Re-register gauges AFTER live feed to keep them at the bottom
260					// (widget Map insertion order = render order)
261					registerConstraintGauges();
262				};
263	
264				const removeBoardWidget = () => {
265					ctx.ui.setWidget("board-live-feed", undefined);
266				};
267	
268				// Initialize state for all target members in config order, then render
269				for (const m of targetMembers) {
270					memberState.set(m.name, { text: "", active: true });
271				}
272				refreshBoardWidget();
273	
274				const results = await Promise.allSettled(
275					targetMembers.map(async (member) => {
276						try {
277							const result = await callBoardMember(
278								member,
279								message,
280								subprocessEnv,
281								signal,
282								(accumulated) => {
283									perMemberText.set(member.name, accumulated);
284									memberState.set(member.name, { text: accumulated, active: true });
285									refreshBoardWidget();
286								},
287								meetingState!.contextFiles,
288								meetingState!.deliberationDir,
289								(toolName, toolCallId, toolArgs) => {
290									appendToolUse(meetingState!.deliberationDir, {
291										agent: member.name,
292										timestamp: new Date().toISOString(),
293										tool_name: toolName,
294										tool_call_id: toolCallId,
295										args: trimToolArgs(toolArgs),
296									});
297								},
298							);
299							respondingMembers.delete(member.name);
300							memberState.set(member.name, { text: result.response, active: false });
301							refreshBoardWidget();
302	
303							// Log the response
304							appendToLog(meetingState!.logPath, {
305								from: member.name,
306								to: "all",
307								message: result.response,
308								timestamp: new Date().toISOString(),
309								type: "response",
310								tokens_in: result.tokensIn,
311								tokens_out: result.tokensOut,
312								cost: result.cost,
313							});
314	
315							// Update stats
316							meetingState!.budgetSpent += result.cost;
317							const stats = memberStats.get(member.name) || {
318								chats: 0,
319								cost: 0,
320								tokensUsed: 0,
321								contextWindow: 256000,
322							};
323							stats.chats += 1;
324							stats.cost += result.cost;
325							stats.tokensUsed = result.contextTokens;
326							memberStats.set(member.name, stats);
327	
328							return { member: member.name, response: result.response, cost: result.cost };
329						} catch (err: any) {
330							respondingMembers.delete(member.name);
331							const errorMsg = `[Error from ${member.name}: ${err.message}]`;
332							perMemberText.set(member.name, errorMsg);
333							memberState.set(member.name, { text: errorMsg, active: false });
334							refreshBoardWidget();
335							return { member: member.name, response: errorMsg, cost: 0 };
336						}
337					}),
338				);
339	
340				// Clear all responding flags and remove widget
341				for (const m of targetMembers) {
342					respondingMembers.delete(m.name);
343				}
344				removeBoardWidget();
345	
346				// Collect results
347				const allResponses: { member: string; response: string; cost: number }[] = [];
348				for (const r of results) {
349					if (r.status === "fulfilled") {
350						allResponses.push(r.value);
351					}
352				}
353	
354	
355				// Compute final constraint state
356				const constraintState = getConstraintState(meetingState);
357	
358				// Build return text
359				let resultText = "";
360				for (const resp of allResponses) {
361					resultText += `\n\n### ${resp.member}\n${resp.response}`;
362				}
363				resultText += "\n\n---\n\n### Constraint State\n";
364				resultText += `- Elapsed: ${constraintState.elapsed_time_minutes} minutes\n`;
365				resultText += `- Budget spent: $${constraintState.budget_spent.toFixed(2)}\n`;
366				resultText += `- Past min time: ${constraintState.past_min_time}\n`;
367				resultText += `- Past min budget: ${constraintState.past_min_budget}\n`;
368				resultText += `- Approaching max time: ${constraintState.approaching_max_time}\n`;
369				resultText += `- Approaching max budget: ${constraintState.approaching_max_budget}\n`;
370				resultText += `- Hit max: ${constraintState.hit_max}\n`;
371	
372				if (constraintState.hit_max) {
373					resultText +=
374						"\n**CONSTRAINT LIMIT REACHED.** You MUST call `end_deliberation` immediately.";
375				}
376	
377				return {
378					content: [{ type: "text", text: resultText.trim() }],
379					details: { responses: allResponses, constraintState },
380				};
381			},
382	
383			renderCall(args, theme) {
384				const toStr =
385					typeof args.to === "string" ? args.to : Array.isArray(args.to) ? args.to.join(", ") : "...";
386				const msgPreview =
387					args.message && args.message.length > 80
388						? args.message.slice(0, 80) + "..."
389						: args.message || "...";
390				let text = theme.fg("toolTitle", theme.bold("converse "));
391				text += theme.fg("accent", `CEO -> ${toStr}`);
392				text += "\n  " + theme.fg("dim", msgPreview);
393				return new Text(text, 0, 0);
394			},
395	
396			renderResult(result, { expanded, isPartial }, theme) {
397				if (isPartial) {
398					const text = result.content?.[0];
399					return new Text(
400						theme.fg("warning", text?.type === "text" ? text.text : "Board members responding..."),
401						0,
402						0,
403					);
404				}
405	
406				const details = result.details as
407					| { responses?: { member: string; response: string; cost: number }[]; constraintState?: ConstraintState }
408					| undefined;
409				const responses = details?.responses || [];
410				const cs = details?.constraintState;
411	
412				let text = theme.fg("success", `${responses.length} response(s)`);
413				if (cs) {
414					text += theme.fg("muted", ` | ${cs.elapsed_time_minutes}min | $${cs.budget_spent.toFixed(2)}`);
415					if (cs.hit_max) text += " " + theme.fg("error", "[MAX REACHED]");
416					else if (cs.approaching_max_time || cs.approaching_max_budget)
417						text += " " + theme.fg("warning", "[APPROACHING MAX]");
418				}
419	
420				if (expanded) {
421					for (const r of responses) {
422						text += `\n\n${theme.fg("accent", theme.bold(r.member))}${theme.fg("dim", ` ($${r.cost.toFixed(4)})`)}`;
423						text += `\n${theme.fg("dim", r.response)}`;
424					}
425				} else {
426					for (const r of responses) {
427						const preview =
428							r.response.length > 100 ? r.response.slice(0, 100) + "..." : r.response;
429						text += `\n  ${theme.fg("accent", r.member)}: ${theme.fg("dim", preview.replace(/\n/g, " "))}`;
430					}
431				}
432	
433				return new Text(text, 0, 0);
434			},
435		});
436	
437		// ── registerTool("end_deliberation") ─────────────────────────
438	
439		pi.registerTool({
440			name: "end_deliberation",
441			label: "End Deliberation",
442			description:
443				"End the deliberation and collect final one-statement positions from all board members. Contrarian speaks last (enforced). After this tool returns, write the memo.",
444			promptSnippet:
445				"End deliberation. Collects final statements from all members (contrarian last). Then write the memo.",
446			promptGuidelines: [
447				"Call end_deliberation when hit_max is true, or when you have sufficient discussion to make a decision.",
448				"After end_deliberation returns, your only job is to write the memo using the write tool.",
449			],
450			parameters: Type.Object({
451				message: Type.String({
452					description:
453						"The CEO's closing prompt to the board (e.g. 'Summarize your final position in one statement.')",
454				}),
455			}),
456	
457			async execute(_toolCallId, params, signal, onUpdate, ctx) {
458				if (!meetingState || (meetingState.phase !== "deliberating" && meetingState.phase !== "ending")) {
459					throw new Error("No active deliberation to end.");
460				}
461	
462				// Guard: check if min constraints are met
463				const cs = getConstraintState(meetingState);
464				if (!cs.past_min_time && !cs.hit_max) {
465					const remainingTime = meetingState.constraints.min_time_minutes - cs.elapsed_time_minutes;
466					throw new Error(
467						`Min time constraint not reached. ${remainingTime.toFixed(1)} minutes remaining before you can end. ` +
468							`Budget spent: $${cs.budget_spent.toFixed(2)}. Keep deliberating.`,
469					);
470				}
471	
472				meetingState.phase = "ending";
473	
474				// Log the end_deliberation prompt
475				appendToLog(meetingState.logPath, {
476					from: "CEO",
477					to: "all",
478					message: params.message,
479					timestamp: new Date().toISOString(),
480					type: "end_deliberation",
481				});
482	
483				// All members give final statements in PARALLEL (including contrarian)
484				const allMembers = [...meetingState.activeMembers];
485	
486				const finalStatements: { member: string; response: string }[] = [];
487	
488				// Live feed widget for final statements
489				const endMemberState: Map<string, { text: string; active: boolean }> = new Map();
490				for (const m of allMembers) {
491					endMemberState.set(m.name, { text: "", active: true });
492				}
493	
494				const refreshEndWidget = () => {
495					ctx.ui.setWidget("board-live-feed", () => ({
496						render(rawWidth: number): string[] {
497							const width = Math.floor(rawWidth * 0.9);
498							const allLines: string[] = [];
499							for (const m of allMembers) {
500								const state = endMemberState.get(m.name);
501								if (!state) continue;
502	
503								const { r, g, b } = parseHexColor(m.color);
504								const bgOpen = `\x1b[48;2;${r};${g};${b}m`;
505								const fgDark = `\x1b[38;2;30;30;30m`;
506								const reset = `\x1b[0m`;
507	
508								const icon = state.active ? "\u{1F4AC}" : "\u{2705}";
509								const status = state.active ? " final statement..." : " done";
510								const header = `${bgOpen}${fgDark} ${icon} ${m.name}${status} ${reset}`;
511								const headerLine = truncateToWidth(header + " ".repeat(rawWidth), rawWidth, "");
512	
513								const lines = state.text.split("\n").filter((l) => l.trim());
514								const lastLine = lines[lines.length - 1] || "";
515								const contentLine = truncateToWidth(
516									"  " + dim(lastLine) + " ".repeat(width),
517									width,
518									"",
519								);
520								allLines.push(headerLine, contentLine);
521							}
522							return allLines;
523						},
524						invalidate() {},
525					}));
526					registerConstraintGauges();
527				};
528	
529				refreshEndWidget();
530	
531				const endResults = await Promise.allSettled(
532					allMembers.map(async (member) => {
533						try {
534							const result = await callBoardMember(
535								member,
536								params.message,
537								subprocessEnv,
538								signal,
539								(accumulated) => {
540									endMemberState.set(member.name, { text: accumulated, active: true });
541									refreshEndWidget();
542								},
543								meetingState!.contextFiles,
544								meetingState!.deliberationDir,
545								(toolName, toolCallId, toolArgs) => {
546									appendToolUse(meetingState!.deliberationDir, {
547										agent: member.name,
548										timestamp: new Date().toISOString(),
549										tool_name: toolName,
550										tool_call_id: toolCallId,
551										args: trimToolArgs(toolArgs),
552									});
553								},
554							);
555	
556							endMemberState.set(member.name, { text: result.response, active: false });
557							refreshEndWidget();
558	
559							// Log final statement
560							appendToLog(meetingState!.logPath, {
561								from: member.name,
562								to: "all",
563								message: result.response,
564								timestamp: new Date().toISOString(),
565								type: "final_statement",
566								tokens_in: result.tokensIn,
567								tokens_out: result.tokensOut,
568								cost: result.cost,
569							});
570	
571							// Update stats
572							meetingState!.budgetSpent += result.cost;
573							const stats = memberStats.get(member.name) || {
574								chats: 0,
575								cost: 0,
576								tokensUsed: 0,
577								contextWindow: 256000,
578							};
579							stats.chats += 1;
580							stats.cost += result.cost;
581							stats.tokensUsed = result.contextTokens;
582							memberStats.set(member.name, stats);
583	
584							return { member: member.name, response: result.response };
585						} catch (err: any) {
