1154	
1155		pi.on("session_start", async (_event, ctx) => {
1156			// Store ctx for gauge widget re-registration
1157			gaugeCtx = ctx;
1158	
1159			// Apply synthwave theme on boot
1160			if (ctx.hasUI) {
1161				ctx.ui.setTheme("synthwave");
1162				setTimeout(() => ctx.ui.setTitle("pi - CEO & Board"), 150);
1163			}
1164	
1165			// Load configuration
1166			config = parseConfig(ctx.cwd);
1167			projectRoot = findProjectRoot(ctx.cwd);
1168	
1169			// Load .env from project root for subprocess env vars
1170			if (projectRoot) {
1171				subprocessEnv = loadDotEnv(projectRoot);
1172			}
1173	
1174			// Set CEO model from ceo.md frontmatter (e.g. "anthropic/claude-opus-4-6")
1175			if (projectRoot) {
1176				const ceoPath = join(projectRoot, ".pi", "ceo-agents", "agents", "ceo.md");
1177				if (existsSync(ceoPath)) {
1178					try {
1179						const ceoRaw = readFileSync(ceoPath, "utf-8");
1180						const { frontmatter: ceoFm } = parseFrontmatter<Record<string, string>>(ceoRaw);
1181						if (ceoFm.model) {
1182							const parts = ceoFm.model.split("/");
1183							const provider = parts.length > 1 ? parts[0] : "anthropic";
1184							const modelName = parts.length > 1 ? parts.slice(1).join("/") : parts[0];
1185							const foundModel = ctx.modelRegistry.find(provider, modelName);
1186							if (foundModel) {
1187								await pi.setModel(foundModel);
1188							}
1189						}
1190					} catch {
1191						// Fall through — use whatever pi defaults to
1192					}
1193				}
1194			}
1195	
1196			// Footer: CEO card (full row) + board member cards
1197			ctx.ui.setFooter((_tui, theme, _footerData) => ({
1198				dispose: () => {},
1199				invalidate() {},
1200				render(width: number): string[] {
1201					const lines: string[] = [];
1202	
1203					// CEO card — full width, same style as board members
1204					const model = ctx.model?.id || "no-model";
1205					const usage = ctx.getContextUsage();
1206					const pct = usage && usage.percent !== null ? usage.percent : 0;
1207					const ctxWindow = ctx.model?.contextWindow || 0;
1208					const ctxK = ctxWindow >= 1000 ? `${Math.round(ctxWindow / 1000)}k` : `${ctxWindow}`;
1209	
1210					const phaseStr = meetingState ? ` [${meetingState.phase}]` : "";
1211	
1212					// CEO uses cyan color from the synthwave palette
1213					const ceoBg = `\x1b[48;2;54;249;246m`;
1214					const fgDark = `\x1b[38;2;30;30;30m`;
1215					const reset = `\x1b[0m`;
1216	
1217					const ceoIcon = meetingState && meetingState.phase === "deliberating" ? " \u{1F4AC} " : " ";
1218					// const ceoLeft = `${ceoIcon}CEO ${model}${phaseStr} `;
1219					const ceoLeft = `${ceoIcon}CEO${phaseStr} `;
1220					const usedTokens = usage && usage.tokens !== null ? usage.tokens : 0;
1221					const remainingTokens = ctxWindow - usedTokens;
1222					const ceoCtxStr = formatTokenCount(Math.max(0, remainingTokens));
1223					const ceoRight = `\u{1F4B0}$${ceoCost.toFixed(2)} \u{1F9E0}${ceoCtxStr} `;
1224					const ceoInner = visibleWidth(ceoLeft) + visibleWidth(ceoRight);
1225					const ceoPad = " ".repeat(Math.max(1, width - ceoInner));
1226					const ceoLine = truncateToWidth(`${ceoBg}${fgDark}${ceoLeft}${ceoPad}${ceoRight}${reset}`, width, "");
1227					lines.push(ceoLine);
1228	
1229					// Gap between CEO and board members
1230					lines.push("");
1231	
1232					// Board member status cards (2 per row, no gaps between rows)
1233					const boardLines = renderBoardStatusLines(width, meetingState?.activeMembers || [], memberStats, respondingMembers);
1234					lines.push(...boardLines);
1235	
1236					return lines;
1237				},
1238			}));
1239	
1240			// Status line
1241			const memberCount = config?.board.length ?? 0;
1242			ctx.ui.setStatus("ceo", `Board: ${memberCount} members`);
1243	
1244			// Startup message — show models in [brackets] for each agent
1245			if (config) {
1246				const c = config.meeting.constraints;
1247	
1248				// Append "1M" context badge for Claude 4-6 models
1249				const modelLabel = (model: string): string =>
1250					/claude-.*-4-6/.test(model) ? `${model} 1M` : model;
1251	
1252				// Read CEO model from frontmatter
1253				let ceoModelStr = "unknown";
1254				if (projectRoot) {
1255					const ceoAgentPath = join(projectRoot, ".pi", "ceo-agents", "agents", "ceo.md");
1256					if (existsSync(ceoAgentPath)) {
1257						try {
1258							const raw = readFileSync(ceoAgentPath, "utf-8");
1259							const { frontmatter: fm } = parseFrontmatter<Record<string, string>>(raw);
1260							if (fm.model) ceoModelStr = fm.model;
1261						} catch {}
1262					}
1263				}
1264	
1265				// Build styled board member lines with per-member colors
1266				const fgFromHex = (hex: string, s: string): string => {
1267					const { r, g, b } = parseHexColor(hex);
1268					return `\x1b[38;2;${r};${g};${b}m${s}\x1b[39m`;
1269				};
1270	
1271				const memberLines: string[] = [];
1272				// CEO line — use cyan (synthwave accent)
1273				memberLines.push(`\n   ${cyan("\u25C6")} ${bold(cyan("CEO"))} ${dim(`[${modelLabel(ceoModelStr)}]`)}`);
1274				for (const b of config.board) {
1275					let memberModel = "unknown";
1276					if (projectRoot) {
1277						const memberPath = join(projectRoot, b.path);
1278						if (existsSync(memberPath)) {
1279							try {
1280								const raw = readFileSync(memberPath, "utf-8");
1281								const { frontmatter: fm } = parseFrontmatter<Record<string, string>>(raw);
1282								if (fm.model) memberModel = fm.model;
1283							} catch {}
1284						}
1285					}
1286					memberLines.push(`\n   ${fgFromHex(b.color, "\u25C6")} ${bold(fgFromHex(b.color, b.name))} ${dim(`[${modelLabel(memberModel)}]`)}`);
1287				}
1288	
1289				ctx.ui.notify(
1290					`${bold(pink("CEO & Board"))} ${dim("\u2014")} ${yellow("Strategic Decision-Making Agent Team")}\n\n` +
1291						`${dim("Time")}    ${cyan(`${c.min_time_minutes}-${c.max_time_minutes}`)} ${dim("min")}\n` +
1292						`${dim("Budget")}  ${green(c.min_budget)}${dim("-")}${green(c.max_budget)}\n` +
1293						`${dim("Editor")}  ${yellow(config.meeting.editor)}\n\n` +
1294						`${bold("Board")}${memberLines.join("")}\n\n` +
1295						`${dim("Run")} ${cyan("/ceo-begin")} ${dim("to start a deliberation.")}`,
1296					"info",
1297				);
1298			} else {
1299				ctx.ui.notify(
1300					"CEO & Board Agent Team\n\n" +
1301						"No configuration found.\n" +
1302						"Create .pi/ceo-agents/ceo-and-board-configuration.yaml",
1303					"warning",
1304				);
1305			}
1306		});
1307	}
