1	// ── Helper Utilities ─────────────────────────────────────────────
2	// Small utility functions: logging, budgets, constraints, session IDs.
3	
4	import { appendFileSync } from "node:fs";
5	import { join } from "node:path";
6	import type { MeetingState, ConstraintState } from "./types";
7	
8	export function generateSessionId(): string {
9		return Math.random().toString(36).substring(2, 8);
10	}
11	
12	export function parseBudget(budget: string): number {
13		return parseFloat(budget.replace(/^\$/, "")) || 0;
14	}
15	
16	export function appendToLog(logPath: string, entry: object): void {
17		appendFileSync(logPath, JSON.stringify(entry) + "\n", "utf-8");
18	}
19	
20	/**
21	 * Trim tool args for logging — truncate each value to 20 chars.
22	 */
23	export function trimToolArgs(args: Record<string, any> | undefined): Record<string, string> {
24		if (!args || typeof args !== "object") return {};
25		const trimmed: Record<string, string> = {};
26		for (const [key, val] of Object.entries(args)) {
27			const str = typeof val === "string" ? val : JSON.stringify(val) ?? "";
28			trimmed[key] = str.length > 24 ? str.slice(0, 10) + "..." + str.slice(-10) : str;
29		}
30		return trimmed;
31	}
32	
33	/**
34	 * Append a tool-use entry to the deliberation's tool-use.jsonl.
35	 */
36	export function appendToolUse(deliberationDir: string, entry: {
37		agent: string;
38		timestamp: string;
39		tool_name: string;
40		tool_call_id?: string;
41		args: Record<string, string>;
42	}): void {
43		const toolLogPath = join(deliberationDir, "tool-use.jsonl");
44		appendFileSync(toolLogPath, JSON.stringify(entry) + "\n", "utf-8");
45	}
46	
47	export function getConstraintState(state: MeetingState): ConstraintState {
48		const elapsedMs = Date.now() - state.startTime;
49		const elapsedMinutes = elapsedMs / 1000 / 60;
50		const minTime = state.constraints.min_time_minutes;
51		const maxTime = state.constraints.max_time_minutes;
52		const minBudget = parseBudget(state.constraints.min_budget);
53		const maxBudget = parseBudget(state.constraints.max_budget);
54		const budgetSpent = state.budgetSpent;
55	
56		const pastMinTime = elapsedMinutes >= minTime;
57		const pastMinBudget = budgetSpent >= minBudget;
58		const approachingMaxTime = elapsedMinutes >= maxTime * 0.8;
59		const approachingMaxBudget = budgetSpent >= maxBudget * 0.8;
60		const hitMaxTime = elapsedMinutes >= maxTime;
61		const hitMaxBudget = budgetSpent >= maxBudget;
62	
63		let hitMaxReason: ConstraintState["hit_max_reason"] = "none";
64		if (hitMaxTime && hitMaxBudget) hitMaxReason = "max_time_and_budget_constraint";
65		else if (hitMaxTime) hitMaxReason = "max_time_constraint";
66		else if (hitMaxBudget) hitMaxReason = "max_budget_constraint";
67	
68		return {
69			elapsed_time_minutes: Math.round(elapsedMinutes * 10) / 10,
70			budget_spent: Math.round(budgetSpent * 100) / 100,
71			past_min_time: pastMinTime,
72			past_min_budget: pastMinBudget,
73			approaching_max_time: approachingMaxTime,
74			approaching_max_budget: approachingMaxBudget,
75			hit_max: hitMaxTime || hitMaxBudget,
76			hit_max_reason: hitMaxReason,
77		};
78	}
