		const raw = readFileSync(configPath, "utf-8");
		const config: CeoConfig = {
			meeting: {
				constraints: {
					min_time_minutes: 5,
					max_time_minutes: 10,
					min_budget: "$2",
					max_budget: "$10",
				},
				editor: "code",
